"use client";

import {
  TraceWiseStatus,
  type TraceWiseStatusProps,
} from "@razorsoft/tracewise-status";

export type TraceWiseStatusBadgeProps = Omit<TraceWiseStatusProps, "variant">;

/**
 * Compact TraceWise status badge.
 * Fetches the public status page once. No API key. Polling stays off unless `refreshInterval` is set.
 */
export function TraceWiseStatusBadge({
  className,
  ...props
}: TraceWiseStatusBadgeProps) {
  return <TraceWiseStatus {...props} className={className} variant="badge" />;
}

"use client";

import {
  TraceWiseStatus,
  type TraceWiseStatusProps,
} from "@razorsoft/tracewise-status";

export type TraceWiseStatusIndicatorProps = Omit<TraceWiseStatusProps, "variant">;

/**
 * Inline TraceWise status indicator.
 * Fetches the public status page once. No API key. Polling stays off unless `refreshInterval` is set.
 */
export function TraceWiseStatusIndicator({
  className,
  ...props
}: TraceWiseStatusIndicatorProps) {
  return (
    <TraceWiseStatus {...props} className={className} variant="indicator" />
  );
}
